{"description":"Focused OCR on lines 4 and 5 with variations","cmd":"python3 - <<'EOF'
from PIL import Image, ImageOps, ImageFilter
import subprocess
im = Image.open('/app/code.png')
# lines from earlier segmentation:
# line4 y 454-497, x 101-662
# line5 y 524-567
for name, box in [('l4',(101,454,662,497)),('l5',(101,524,662,567))]:
    crop = im.crop(box)
    print('====',name,'orig size',crop.size)
    for scale in [2,4]:
        big = crop.resize((crop.width*scale, crop.height*scale), Image.LANCZOS).convert('L')
        for invert in [False, True]:
            g = big if not invert else ImageOps.invert(big)
            for mode_name,img in [('raw',g),('otsu',g.point(lambda p: 255 if p> (g.getextrema()[0]+g.getextrema()[1])/2 else 0))]:
                fn=f'/app/{name}_{scale}_{invert}_{mode_name}.png'
                img.save(fn)
                for psm in ['7','6','13']:
                    r = subprocess.run(['tesseract',fn,'stdout','--psm',psm],capture_output=True,text=True)
                    txt = r.stdout.strip().replace('\n',' ')
                    if txt:
                        print(f'scale{scale} inv{invert} {mode_name} psm{psm}: {txt}')
EOF"}
